// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { mapFrame, placesOf } from "../../../main/frontend/graph-explorer/graph-literals.ts";
import { mergeTriples } from "../../../main/frontend/graph-explorer/graph-operations.ts";
import { bindingsToTriples } from "../../../main/frontend/graph-explorer/graph-terms.ts";

const GEO = "http://www.w3.org/2003/01/geo/wgs84_pos#";
const uri = (value) => ({ type: "uri", value });
const decimal = (value) => ({ type: "literal", value, datatype: "http://www.w3.org/2001/XMLSchema#decimal" });
const row = (source, predicate, target) => ({ source, predicate: uri(predicate), target });

function places(rows) {
  const graph = mergeTriples({ nodes: [], edges: [], revision: 0 }, bindingsToTriples(rows));
  const nodeById = new Map(graph.nodes.map((node) => [node.id, node]));
  return placesOf(graph.edges, nodeById).map((place) => [place.node.id, place.latitude, place.longitude]);
}

test("geo:lat with geo:long and schema:latitude with schema:longitude place a resource", () => {
  assert.deepEqual(
    places([
      row(uri("urn:oslo"), `${GEO}lat`, decimal("59.91")),
      row(uri("urn:oslo"), `${GEO}long`, decimal("10.75")),
      row(uri("urn:bergen"), "https://schema.org/latitude", decimal("60.39")),
      row(uri("urn:bergen"), "http://schema.org/longitude", { type: "literal", value: "5.32" }),
      row(uri("urn:nowhere"), `${GEO}lat`, decimal("12")),
    ]),
    [
      ["urn:oslo", 59.91, 10.75],
      ["urn:bergen", 60.39, 5.32],
    ],
  );
});

test("a WKT point places its subject, and coordinates on a schema:geo node place its owner", () => {
  assert.deepEqual(
    places([
      row(uri("urn:trondheim"), "http://www.wikidata.org/prop/direct/P625", {
        type: "literal",
        value: "Point(10.39 63.43)",
        datatype: "http://www.opengis.net/ont/geosparql#wktLiteral",
      }),
      row(uri("urn:acme"), "http://schema.org/geo", { type: "bnode", value: "g" }),
      row({ type: "bnode", value: "g" }, "http://schema.org/latitude", decimal("58.97")),
      row({ type: "bnode", value: "g" }, "http://schema.org/longitude", decimal("5.73")),
    ]),
    [
      ["urn:trondheim", 63.43, 10.39],
      ["urn:acme", 58.97, 5.73],
    ],
  );
});

test("values outside the globe are not places", () => {
  assert.deepEqual(
    places([
      row(uri("urn:x"), `${GEO}lat`, decimal("91")),
      row(uri("urn:x"), `${GEO}long`, decimal("10")),
      row(uri("urn:y"), "urn:wkt", { type: "literal", value: "Point(200 10)" }),
    ]),
    [],
  );
});

test("the map frames every place, with a margin and a minimum size", () => {
  assert.deepEqual(mapFrame([{ latitude: 59.9, longitude: 10.7 }, { latitude: 60.4, longitude: 5.3 }]), {
    west: 4.76,
    south: 59.85,
    east: 11.24,
    north: 60.45,
  });
  assert.deepEqual(mapFrame([{ latitude: 59.9, longitude: 10.7 }]), { west: 10.6, south: 59.8, east: 10.8, north: 60 });
});

import { parseGraphDate } from "../../../main/frontend/graph-explorer/graph-literals.ts";
import { histogram, numericSeriesOf } from "../../../main/frontend/graph-explorer/chart-data.ts";

const XSD = "http://www.w3.org/2001/XMLSchema#";
const lit = (value, datatype) => ({ id: `lit:${value}:${datatype}`, label: value, termValue: value, kind: "literal", datatype });

test("dates come from date-typed values and ISO dates, never from plain numbers", () => {
  assert.equal(parseGraphDate(lit("2001", `${XSD}integer`)), null);
  assert.equal(parseGraphDate(lit("2001", undefined)), null);
  assert.equal(parseGraphDate(lit("12", undefined)), null);
  assert.equal(parseGraphDate(lit("2001", `${XSD}gYear`)).toISOString(), "2001-01-01T00:00:00.000Z");
  assert.equal(parseGraphDate(lit("2001-05", `${XSD}gYearMonth`)).toISOString(), "2001-05-01T00:00:00.000Z");
  assert.equal(parseGraphDate(lit("1986-04-02", `${XSD}date`)).toISOString(), "1986-04-02T00:00:00.000Z");
  assert.equal(parseGraphDate(lit("1986-04-02", undefined)).toISOString(), "1986-04-02T00:00:00.000Z");
  assert.ok(parseGraphDate(lit("2026-10-14T19:34:29Z", `${XSD}dateTime`)));
  assert.equal(parseGraphDate(lit("12:00:00", `${XSD}time`)), null);
});

test("numeric values are charted per predicate, the predicate with most values first", () => {
  const graph = mergeTriples(
    { nodes: [], edges: [], revision: 0 },
    bindingsToTriples([
      row(uri("urn:a"), "urn:age", decimal("39")),
      row(uri("urn:b"), "urn:age", decimal("45")),
      row(uri("urn:c"), "urn:age", decimal("28")),
      row(uri("urn:a"), `${GEO}lat`, decimal("59.9")),
      row(uri("urn:b"), `${GEO}lat`, decimal("60.4")),
      row(uri("urn:a"), "urn:since", decimal("2001")),
      row(uri("urn:a"), "urn:name", { type: "literal", value: "Alice" }),
    ]),
  );
  const nodeById = new Map(graph.nodes.map((node) => [node.id, node]));
  const series = numericSeriesOf(graph.edges, nodeById);
  assert.deepEqual(series.map((entry) => [entry.predicate, entry.values]), [
    ["urn:age", [39, 45, 28]],
    [`${GEO}lat`, [59.9, 60.4]],
  ], "a predicate with a single value has nothing to distribute");
  const bins = histogram([1, 2, 3, 4, 10]);
  assert.equal(bins.reduce((sum, bin) => sum + bin.count, 0), 5);
  assert.equal(bins[0].minimum, 1);
  assert.equal(bins.at(-1).maximum, 10);
});
